import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    const member = await apiAs("member");

    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Lock Test"),
        category: "logistics",
        contact_email: `ops.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@acmefreight.example`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();

    const kinds = ["w9", "insurance_certificate", "contract"] as const;
    const documentIds: string[] = [];
    for (const kind of kinds) {
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 test document"),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
      documentIds.push((await upload.json()).id);
    }

    for (const documentId of documentIds) {
      await expect
        .poll(async () => {
          const res = await member.get(`/api/documents/${documentId}`);
          return (await res.json()).status;
        })
        .toBe("extracted");
    }

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitted.status(), await submitted.text()).toBe(200);

    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}`);
        return (await res.json()).status;
      })
      .toBe("in_review");

    const res = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });
    expect(res.status(), await res.text()).toBe(409);
    expect((await res.json()).error.code, await res.text()).toBe("vendor_locked");
  });
});
